const repo = $env.GITHUB_REPO || 'owner/repo';
const token = $env.GITHUB_TOKEN;
const lang = $env.LANGUAGE || 'EN';
const webhook = $env.DISCORD_WEBHOOK_URL;
const apiKey = $env.ANTHROPIC_API_KEY;

const since = new Date(Date.now() - 7 * 24 * 60 * 60 * 1000).toISOString();
const headers = { 'Authorization': `token ${token}`, 'User-Agent': 'n8n' };

const commits = await this.helpers.httpRequest({ method: 'GET', url: `https://api.github.com/repos/${repo}/commits?since=${since}`, headers });
const issues = await this.helpers.httpRequest({ method: 'GET', url: `https://api.github.com/repos/${repo}/issues?state=closed&since=${since}`, headers });
const prs = await this.helpers.httpRequest({ method: 'GET', url: `https://api.github.com/repos/${repo}/pulls?state=closed&sort=updated&direction=desc`, headers });

const prompt = `Generate a ${lang} narrative summary of this week's development for repo ${repo}.\n\nCommits: ${JSON.stringify((commits.data || commits).slice(0, 15))}\nClosed Issues: ${JSON.stringify((issues.data || issues).slice(0, 15))}\nMerged PRs: ${JSON.stringify((prs.data || prs).filter(p => p.merged_at).slice(0, 15))}`;

const claudeRes = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api.anthropic.com/v1/messages',
  headers: { 'x-api-key': apiKey, 'anthropic-version': '2023-06-01', 'content-type': 'application/json' },
  body: JSON.stringify({ model: 'claude-sonnet-4-20250514', max_tokens: 1024, messages: [{ role: 'user', content: prompt }] })
});

const summary = claudeRes.content[0].text;

await this.helpers.httpRequest({
  method: 'POST',
  url: webhook,
  headers: { 'content-type': 'application/json' },
  body: JSON.stringify({ content: `**Weekly Dev Summary for ${repo}**\n\n${summary}` })
});

return [{ json: { success: true, repo, summary } }];
